CREATE TABLE hiring_stages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE CHECK(length(name) BETWEEN 1 AND 80), position integer NOT NULL);
INSERT INTO hiring_stages(name,position) VALUES ('Applied',0),('Screen',1),('Interview',2),('Offer',3),('Hired',4),('Rejected',5);
CREATE TABLE hiring_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), description text NOT NULL CHECK(length(description) BETWEEN 1 AND 12000), location text NOT NULL CHECK(length(location) BETWEEN 1 AND 200), open boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hiring_team(job_id uuid NOT NULL REFERENCES hiring_jobs(id), user_id uuid NOT NULL REFERENCES app_users(id), PRIMARY KEY(job_id,user_id));
CREATE TABLE hiring_candidates(user_id uuid PRIMARY KEY REFERENCES app_users(id), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200));
CREATE TABLE hiring_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES hiring_jobs(id), candidate_id uuid NOT NULL REFERENCES hiring_candidates(user_id), stage_id uuid NOT NULL REFERENCES hiring_stages(id) ON DELETE RESTRICT, cv_key text NOT NULL UNIQUE, cv_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(job_id,candidate_id));
CREATE INDEX hiring_applications_candidate ON hiring_applications(candidate_id);
CREATE TABLE hiring_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES hiring_applications(id), author_id uuid NOT NULL REFERENCES app_users(id), body text NOT NULL CHECK(length(body) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hiring_ratings(application_id uuid NOT NULL REFERENCES hiring_applications(id), user_id uuid NOT NULL REFERENCES app_users(id), rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), PRIMARY KEY(application_id,user_id));
CREATE TABLE hiring_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES hiring_applications(id), subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','sent','not-sent','unknown')), created_at timestamptz NOT NULL DEFAULT now());
